private void joinForkedArms(Label groupStart, String[] tasks, int[] taskVars) {
    final int n = tasks.length;
    Label groupEnd = new Label();
    Label handler = new Label();
    Label done = new Label();

    mv.visitLabel(groupEnd);
    mv.visitJumpInsn(GOTO, done);

    mv.visitLabel(handler);
    int thrown = mv.createCompilerLocal("thrown", "Ljava/lang/Throwable;");
    mv.visitVarInsn(ASTORE, thrown);
    // An error of the JVM itself, as a stack overflow, can leave a forked
    // arm that nothing will run: it is thrown on without the joins.
    Label rethrow = new Label();
    mv.visitVarInsn(ALOAD, thrown);
    mv.visitTypeInsn(INSTANCEOF, "java/lang/VirtualMachineError");
    mv.visitJumpInsn(IFNE, rethrow);
    for (int i = 1; i < n; i++) {
        mv.visitVarInsn(ALOAD, taskVars[i]);
        mv.visitMethodInsn(INVOKEVIRTUAL, tasks[i], "joinIfForked", "()V");
    }
    mv.visitLabel(rethrow);
    mv.visitVarInsn(ALOAD, thrown);
    mv.disposeCompilerLocal(thrown);
    mv.visitInsn(ATHROW);

    mv.visitLabel(done);
    mv.visitTryCatchBlock(groupStart, groupEnd, handler, "java/lang/Throwable");

    // Most recently created first.
    for (int i = 1; i < n; i++)
        mv.disposeCompilerLocal(taskVars[i]);
}
    return dotProduct;
}

/* For a group of arms that completes abruptly: waits for this arm
 * where it was forked, and takes what it threw.  An arm that was never
 * forked is not run.  The current task is saved and restored around the
 * join, as joinOrRun does. */
public final void joinIfForked() {
    if (actuallyForked == UNFORKED) return;
    Thread thread = Thread.currentThread();
    if (thread instanceof FortressTaskRunner) {
        FortressTaskRunner ftr = (FortressTaskRunner) thread;
        BaseTask saved = ftr.task();
        try {
            this.quietlyJoin();
        } finally {
            ftr.setTask(saved);
        }
    } else {
        this.quietlyJoin();
    }
}

